use std::sync::Mutex;

use crate::database::{DatabaseError, DatabaseResult, Value};

/// The identifier format generated by an Eloquent model.
#[derive(Clone, Copy)]
pub enum UniqueId {
    Uuid,
    Ulid,
}

impl UniqueId {
    pub(super) fn generate(self) -> DatabaseResult<String> {
        match self {
            Self::Uuid => Ok(uuid::Uuid::now_v7().to_string()),
            Self::Ulid => {
                static GENERATOR: Mutex<ulid::Generator> = Mutex::new(ulid::Generator::new());
                GENERATOR
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .generate()
                    .map(|id| id.to_string().to_ascii_lowercase())
                    .map_err(|_| DatabaseError::InvalidQuery("ULID generation"))
            }
        }
    }

    pub(super) fn valid(self, value: &str) -> bool {
        match self {
            Self::Uuid => value.len() == 36 && uuid::Uuid::parse_str(value).is_ok(),
            Self::Ulid => {
                value
                    .as_bytes()
                    .first()
                    .is_some_and(|byte| matches!(byte, b'0'..=b'7'))
                    && ulid::Ulid::from_string(value).is_ok()
            }
        }
    }
}

pub(super) fn is_empty(value: Option<Value>) -> bool {
    match value {
        None | Some(Value::Null | Value::Bool(false)) => true,
        Some(Value::Integer(value)) => value == 0,
        Some(Value::Unsigned(value)) => value == 0,
        Some(Value::Real(value)) => value == 0.0,
        Some(Value::Text(value)) => value.is_empty() || value == "0",
        Some(Value::Bytes(value)) => value.is_empty() || value == b"0",
        Some(Value::Json(value)) => match value {
            serde_json::Value::Null | serde_json::Value::Bool(false) => true,
            serde_json::Value::String(value) => value.is_empty() || value == "0",
            serde_json::Value::Number(value) => value.as_f64() == Some(0.0),
            serde_json::Value::Array(value) => value.is_empty(),
            _ => false,
        },
        _ => false,
    }
}
